    "summary": "Cả 就 (jiù) và 才 (cái) đều đứng trước động từ nhưng mang sắc thái tâm lý trái ngược: 就 biểu thị hành động xảy ra sớm, nhanh hoặc thuận lợi hơn dự kiến (thường đi kèm 了 nếu đã xảy ra). 才 biểu thị hành động xảy ra muộn, chậm hoặc tốn công sức mới đạt được (tuyệt đối không thêm 了 ngữ khí ở cuối câu).",
    "deepNotesHtml": "<p><strong>1. Bản chất tâm lý người nói:</strong> Tiếng Việt thường dịch <code>就</code> (jiù — đã, là liền) và <code>才</code> (cái — mới) nhưng ranh giới trong tiếng Trung nằm ở cảm nhận chủ quan về <em>tốc độ, thời điểm và số lượng</em>. Nếu 7 giờ 30 đã đến lớp trước giờ học 8 giờ, người nói cảm thấy sớm nên dùng <code>七点半就到了</code> (qī diǎn bàn jiù dào le — 7 rưỡi đã đến rồi). Ngược lại, 8 giờ 30 mới tới là muộn, phải dùng <code>八点半才到</code> (bā diǎn bàn cái dào — 8 rưỡi mới đến).</p><p><strong>2. Quy tắc trợ từ <code>了</code> (le):</strong> Đây là bẫy kinh điển ở HSK 4. Câu dùng <code>就</code> diễn tả việc đã hoàn thành sớm thường kết thúc bằng <code>了</code>, còn câu dùng <code>才</code> nhấn mạnh sự chậm trễ tuyệt đối không dùng <code>了</code> ở cuối câu. Nếu chỉ số lượng ít, <code>才</code> mang nghĩa \"mới chỉ\" như <code>他才二十岁</code> (tā cái èrshí suì — anh ấy mới 20 tuổi).</p><p><strong>3. Cấu trúc điều kiện – nối tiếp:</strong> Dùng <code>一…就…</code> (yī… jiù… — hễ… là liền…) cho hai hành động nối tiếp tức thì, còn <code>才</code> thường đi cùng <code>只有…才…</code> (zhǐyǒu… cái… — chỉ có… mới…) để nhấn mạnh điều kiện duy nhất.</p>",
