    "summary": "Cả 再 (zài) và 又 (yòu) đều dịch là 'lại, nữa' khi chỉ hành động lặp lại, nhưng ranh giới thời gian cực kỳ dứt khoát: 又 dùng cho việc đã hoặc đang lặp lại trong thực tế; 再 dùng cho việc chưa xảy ra, dự định tương lai, lời khuyên hoặc câu điều kiện.",
    "deepNotesHtml": "<p><strong>1. Đường ranh Quá khứ – Tương lai:</strong> Khi sự việc đã tái diễn trước thời điểm nói, ta bắt buộc chọn <code>又</code> (yòu — lại nữa rồi), ví dụ <code>今天又下雨了</code> (jīntiān yòu xià yǔ le — hôm nay lại mưa nữa rồi). Khi sự việc chưa xảy ra và chỉ là dự tính sắp tới, ta dùng <code>再</code> (zài — lại, nữa), ví dụ <code>明天再来</code> (míngtiān zài lái — ngày mai lại đến nhé).</p><p><strong>2. Dấu hiệu nhận biết trong đề thi HSK 4:</strong> Nếu câu có trợ từ động thái <code>了</code> (le) ở cuối hoặc sau động từ, hoặc có mốc thời gian quá khứ như <code>昨天</code> (zuótiān — hôm qua), <code>刚才</code> (gāngcái — vừa nãy), đáp án gần như chắc chắn là <code>又</code>. Ngược lại, nếu trước chỗ trống có động từ năng nguyện như <code>想</code> (xiǎng — muốn), <code>要</code> (yào — sẽ/cần), <code>能</code> (néng — có thể) hoặc cấu trúc <code>先…再…</code> (xiān… zài… — trước… rồi mới…), phải chọn <code>再</code>.</p><p><strong>3. Mở rộng ý nghĩa đặc biệt:</strong> Trong câu phủ định nhẹ hoặc nhượng bộ, <code>再…也…</code> (zài… yě… — có… hơn nữa cũng…) như <code>再忙也要休息</code> (zài máng yě yào xiūxi — bận mấy cũng phải nghỉ ngơi) chỉ dùng <code>再</code>, không dùng <code>又</code>.</p>",
