    "summary": "Bốn cặp liên từ nòng cốt của câu ghép HSK 4. Người học cần nắm chắc quy tắc đặt vị trí chủ ngữ (cùng chủ ngữ thì liên từ đứng sau, khác chủ ngữ thì đứng trước) và phân biệt rõ điều kiện đủ (只要…就…) với điều kiện duy nhất (只有…才…).",
    "deepNotesHtml": "<p><strong>1. Quy tắc vị trí chủ ngữ:</strong> Khi hai vế có <em>cùng một chủ ngữ</em>, chủ ngữ đứng trước liên từ đầu tiên: <code>他不但会说汉语，而且会写汉字</code> (tā búdàn huì shuō Hànyǔ, érqiě huì xiě Hànzì — anh ấy không những biết nói tiếng Trung mà còn biết viết chữ Hán). Khi hai vế <em>khác chủ ngữ</em>, liên từ đứng đầu câu trước mỗi chủ ngữ: <code>不但他喜欢，而且我也喜欢</code> (búdàn tā xǐhuan, érqiě wǒ yě xǐhuan — không chỉ anh ấy thích mà tôi cũng thích).</p><p><strong>2. Phân biệt <code>只要…就…</code> và <code>只有…才…</code>:</strong> Cặp <code>只要…就…</code> (zhǐyào… jiù… — chỉ cần… thì…) nêu điều kiện dễ đạt hoặc điều kiện đủ; còn <code>只有…才…</code> (zhǐyǒu… cái… — chỉ có… mới…) nhấn mạnh điều kiện bắt buộc duy nhất, thiếu nó thì kết quả không thể thành hiện thực.</p><p><strong>3. Lưu ý cặp nhượng bộ <code>虽然…但是…</code>:</strong> Khác với nhiều ngôn ngữ phương Tây, trong tiếng Trung chuẩn, <code>虽然</code> (suīrán — tuy rằng) luôn đi cặp trọn vẹn với <code>但是</code> hoặc <code>可是</code> (dànshì / kěshì — nhưng) ở vế sau.</p>",
