    "formula": "Kiêm ngữ: S + V1(请/叫/让/劝) + O(Kiêm ngữ) + V2  |  Liên động: S + V1 + (O1) + V2 + (O2)",
    "summary": "Câu kiêm ngữ có hai động từ trong đó tân ngữ của động từ thứ nhất đồng thời làm chủ ngữ cho động từ thứ hai. Câu liên động lại do một chủ ngữ duy nhất thực hiện liên tiếp hai hành động theo thứ tự thời gian hoặc phương thức trước, mục đích sau.",
    "deepNotesHtml": "<p><strong>1. Cơ chế Câu kiêm ngữ:</strong> Động từ thứ nhất thường mang nghĩa nhờ vả, sai khiến hoặc yêu cầu như <code>请</code> (qǐng — mời), <code>叫</code> (jiào — bảo), <code>让</code> (ràng — để/bắt), <code>劝</code> (quàn — khuyên), <code>派</code> (pài — cử/phái). Trong <code>老师让我回答问题</code> (lǎoshī ràng wǒ huídá wèntí — cô giáo bảo tôi trả lời câu hỏi), từ <code>我</code> vừa chịu tác động của <code>让</code>, vừa trực tiếp thực hiện <code>回答</code>. Lưu ý dạng phủ định hoặc cấm đoán phải đặt <code>不/没/别</code> trước động từ thứ nhất: <code>别让他知道</code> (bié ràng tā zhīdào — đừng để anh ấy biết).</p><p><strong>2. Trật tự Câu liên động:</strong> Người Việt hay nói \"đi Bắc Kinh bằng máy bay\", nhưng tiếng Trung luôn đặt phương thức hoặc công cụ lên trước mục đích: <code>坐飞机去北京</code> (zuò fēijī qù Běijīng — đi máy bay đến Bắc Kinh), hay <code>用筷子吃饭</code> (yòng kuàizi chīfàn — dùng đũa ăn cơm).</p><p><strong>3. Phân biệt nhanh:</strong> Kiêm ngữ đổi chủ thể thực hiện giữa động từ một và hai; liên động giữ nguyên một chủ thể từ đầu đến cuối câu.</p>",
    "examples": [
      {
        "zh": "经理派小李去上海参加这次会议。",
        "py": "Jīnglǐ pài Xiǎo Lǐ qù Shànghǎi cānjiā zhè cì huìyì.",
        "vi": "Giám đốc cử Tiểu Lý đi Thượng Hải tham gia cuộc họp lần này."
      },
      {
        "zh": "爸爸每天都让我多喝水、早点儿睡觉。",
        "py": "Bàba měitiān dōu ràng wǒ duō hē shuǐ, zǎodiǎnr shuìjiào.",
        "vi": "Ngày nào bố cũng bảo tôi uống nhiều nước và đi ngủ sớm."
      },
      {
        "zh": "我打算明天骑自行车去书店买两本小说。",
        "py": "Wǒ dǎsuàn míngtiān qí zìxíngchē qù shūdiàn mǎi liǎng běn xiǎoshuō.",
        "vi": "Tôi định ngày mai đạp xe đến hiệu sách mua hai cuốn tiểu thuyết."
      },
      {
        "zh": "医生劝他戒烟，别再熬夜了。",
        "py": "Yīshēng quàn tā jièyān, bié zài áoyè le.",
        "vi": "Bác sĩ khuyên anh ấy bỏ thuốc lá, đừng thức khuya nữa."
      }
    ],
    "commonMistakes": [
      "❌ 我去北京坐飞机 → ✅ 我坐飞机去北京 (Câu liên động đặt phương tiện 坐飞机 trước mục đích 去北京).",
      "❌ 别告诉他让这件事 → ✅ 别让他知道这件事 (Tân ngữ kiêm ngữ 他 đứng giữa 让 và động từ sau).",
      "❌ 妈妈叫我没去 → ✅ 妈妈叫我别去 / 妈妈没叫我去 (Khi khuyên/cấm không làm gì dùng 别/不要 trước V2, phủ định sự việc đã diễn ra đặt 没 trước V1)."
    ],
