      "❌ 我们商量商量一次 → ✅ 我们商量商量 / 我们商量一次 (Động từ trùng điệp không dùng kèm số lần).",
      "❌ 散步散步 → ✅ 散散步 (Động từ ly hợp 散步 trùng điệp theo mẫu AAB là 散散步, không lặp ABAB)."
