      {
        "zh": "这项传统手工艺已经在这座村庄流传下来几百年了。",
        "py": "Zhè xiàng chuántǒng shǒugōngyì yǐjīng zài zhè zuò cūnzhuāng liúchuán xiàlái jǐbǎi nián le.",
        "vi": "Nghề thủ công truyền thống này đã được lưu truyền lại ở ngôi làng này suốt mấy trăm năm rồi."
      }
