    "summary": "Ba cặp từ cực kỳ dễ nhầm trong phần Chọn từ điền chỗ trống HSK 5 vì mặt chữ và nghĩa gần nhau nhưng từ loại và chức năng câu khác hẳn. Điểm mấu chốt nằm ở khả năng làm định ngữ/vị ngữ và sắc thái bất ngờ hay tần suất.",
    "deepNotesHtml": "<p><strong>1. Cặp <code>偶然</code> (ǒurán) và <code>偶尔</code> (ǒu'ěr):</strong><br>- <code>偶然</code> (ngẫu nhiên, tình cờ): trái nghĩa với <code>必然</code> (tất nhiên). Nó là <strong>tính từ</strong> kiêm phó từ, làm được vị ngữ (<code>这件事很偶然</code> — chuyện này rất tình cờ) và định ngữ (<code>一次偶然的机会</code> — một cơ hội tình cờ).<br>- <code>偶尔</code> (thỉnh thoảng, đôi khi): trái nghĩa với <code>经常</code> (thường xuyên). Nó chỉ là <strong>phó từ</strong> chỉ tần suất thấp, tuyệt đối không nhận <code>很</code> hay đứng trước <code>的 + Danh từ</code>.</p><p><strong>2. Cặp <code>突然</code> (tūrán) và <code>忽然</code> (hūrán):</strong><br>Khi làm trạng ngữ (<code>突然/忽然下起雨来</code>), cả hai thay thế được cho nhau. Nhưng <code>突然</code> là tính từ nên đứng sau <code>很</code> (<code>太突然了</code> — đột ngột quá), làm định ngữ (<code>突然的变化</code> — biến đổi đột ngột) và bổ ngữ được (<code>来得很突然</code>); còn <code>忽然</code> chỉ là phó từ.</p><p><strong>3. Cặp <code>居然</code> và <code>竟然</code>:</strong> Cả hai đều chỉ sự kinh ngạc vượt dự đoán, nhưng <code>竟然</code> sắc thái trang trọng hơn và thường dùng với việc hiếm thấy nghiêm trọng, còn <code>居然</code> linh hoạt trong khẩu ngữ.</p>",
