    "deepNotesHtml": "<p><strong>1. Giải nghĩa từng thành ngữ cốt lõi:</strong><br>- <code>专心致志</code> (zhuānxīn-zhìzhì — chuyên tâm chí thú): dồn toàn bộ tinh thần và ý chí vào một việc, thường làm trạng ngữ đi kèm <code>地</code> (<code>专心致志地听讲</code>) hoặc làm vị ngữ.<br>- <code>半途而废</code> (bàntú-érfèi — bỏ dở giữa đường): làm việc được nửa chừng rồi bỏ cuộc không làm tới đích, hay đi trong câu khuyên răn phủ định <code>千万不能半途而废</code>.<br>- <code>坚持不懈</code> (jiānchí-búxiè — kiên trì không mệt mỏi): bền bỉ nỗ lực không lơi lỏng, hay làm vị ngữ hoặc trạng ngữ <code>坚持不懈地努力</code>.<br>- <code>熟能生巧</code> (shúnéng-shēngqiǎo — quen tay hay việc / trăm hay không bằng tay quen): luyện tập nhiều thành thuần thục rồi sẽ nảy sinh sự khéo léo, thường đứng độc lập làm phân câu.</p><p><strong>2. Lưu ý ngữ pháp khi viết câu:</strong> Tuyệt đối không gắn thêm tân ngữ trực tiếp vào sau các thành ngữ vốn đã trọn vẹn như <code>专心致志学习</code> (cần thêm <code>地</code> thành <code>专心致志地学习</code>).</p>",
