      "❌ 我莫名其妙这个问题 → ✅ 这个问题让我感到莫名其妙 (莫名其妙 không mang tân ngữ trực tiếp phía sau).",
      "❌ 这个办法非常不可思议地好 → ✅ 这个办法简直不可思议 / 妙极了 (Không ghép 不可思议 làm phó từ mức độ cho tính từ khác)."
