        "py": "Tīngdào xuéxiào xià zhōu zǔzhī chūnyóu de xiāoxi, háizimen gègè xìnggāo-cǎiliè de huānhū qǐlái.",
        "vi": "Nghe tin tuần sau trường tổ chức du xuân, lũ trẻ đứa nào đứa nấy hớn hở reo hò lên."
