      "❌ 考完试大家垂头丧气地去庆祝 → Ngược nghĩa! 垂头丧气 là ủ rũ thất vọng; đi ăn mừng phải dùng 兴高采烈.",
      "❌ 天空中飘着五颜六色的雨 → ✅ 公园里开满了五颜六色的鲜花 (五颜六色 tả vật có nhiều màu rực rỡ)."
