    "formula": "A 之 B (= A 的 B)  |  所 + V (thứ được V)  |  V/Tính từ + 者 (người/vật...)  |  其 (nó / của nó)",
    "summary": "Sáu hư từ cổ văn ngắn gọn xuất hiện thường xuyên trong văn bản HSK 6 để rút ngắn câu và tăng tính học thuật. Hiểu quy luật quy đổi sang tiếng Trung hiện đại giúp bạn đọc hiểu báo chí, hợp đồng và văn nghị luận nhanh gấp đôi.",
    "deepNotesHtml": "<p><strong>1. Quy đổi 6 hư từ cổ văn sang ngữ pháp hiện đại:</strong><br>- <code>之</code> (zhī): tương đương chữ <code>的</code> trong cụm danh từ trang trọng (<code>成功之路</code> — con đường thành công, <code>百分之八十</code> — 80 phần trăm), hoặc làm đại từ thay tân ngữ sau động từ (<code>取而代之</code> — thay thế nó).<br>- <code>所</code> (suǒ): đứng trước động từ để danh từ hóa đối tượng chịu tác động (<code>所见所闻</code> — những điều tai nghe mắt thấy, <code>所需资金</code> — nguồn vốn cần thiết).<br>- <code>者</code> (zhě): gắn sau động từ/tính từ để chỉ người hoặc vật mang đặc điểm đó (<code>参与者</code> — người tham gia, <code>前者 / 后者</code> — cái trước / cái sau).<br>- <code>其</code> (qí): tương đương <code>他/它/他的</code> (<code>其中</code> — trong số đó, <code>其实</code> — thực ra).<br>- <code>而</code> (ér): nối hai vế song song (<code>而</code> = và/mà) hoặc tương phản (<code>然而</code> — thế nhưng).<br>- <code>以</code> (yǐ): nghĩa là \"bằng, dùng\" hoặc \"để nhằm mục đích\" (<code>以便</code> — để tiện, <code>以免</code> — để tránh).</p>",
