      "❌ 本着为人民服务为宗旨 → ✅ 本着为人民服务的宗旨 / 以为人民服务为宗旨 (Không trộn 本着…的 và 以…为).",
      "❌ 围绕以质量为中心开展工作 → ✅ 围绕质量开展工作 / 以质量为中心开展工作 (Không trộn 围绕 và 以…为中心)."
