    "formula": "以至 (đến mức, rộng/nhiều lên, tốt hay xấu đều được) vs 以致 (đến nỗi gây hậu quả xấu)  |  从而 (kết quả) vs 进而 (bước kế cao hơn)",
    "summary": "Cặp '以至' và '以致' đồng âm (yǐzhì) và chỉ khác nhau một chữ nhưng lại kiểm tra gắt gao nhất ở HSK 6. Nắm rõ phạm vi tích cực/tiêu cực và quy mô mở rộng giúp không bao giờ mất điểm oan ở phần điền từ.",
    "deepNotesHtml": "<p><strong>1. Cặp đồng âm <code>以至</code> và <code>以致</code> (cùng đọc yǐzhì):</strong><br>- <code>以至</code> (cho đến tận, đến nỗi mà): nhấn mạnh sự mở rộng dần về thời gian, không gian, số lượng hoặc mức độ (<code>从早到晚，以至深夜</code> — từ sáng tới tối, cho đến tận đêm khuya; <code>他非常努力，以至忘了吃饭</code> — cố gắng đến mức quên ăn). Dùng được cho cả kết quả tích cực, trung tính lẫn tiêu cực, cũng hay xuất hiện dưới dạng <code>以至于</code>.<br>- <code>以致</code> (đến nỗi mà): <strong>chỉ nối nguyên nhân với hậu quả xấu hoặc không mong muốn</strong> ở vế sau (<code>由于长期缺乏沟通，以致双方产生严重误会</code>). Không bao giờ dùng <code>以致</code> cho thành công hay mở rộng phạm vi thời gian-địa điểm.</p><p><strong>2. Phân biệt nhanh <code>从而</code>, <code>进而</code> và <code>甚至</code>:</strong> <code>从而</code> chốt lại kết quả; <code>进而</code> tiến tiếp sang giai đoạn kế; <code>甚至</code> nhấn mạnh trường hợp cực đoan nhất.</p>",
