    "id": "hsk6_aspect_register_comp",
    "level": 6,
    "category": "Bổ ngữ",
    "title": "Bổ ngữ kết quả & xu hướng sắc thái văn viết (下来/起来/出来/到/成 trong nghị luận)",
    "formula": "V + 下来 (ổn định / lắng xuống / truyền lưu)  |  V + 起来 (tổng hợp / bắt đầu)  |  V + 到/成 (đạt tầm vóc / chuyển hóa)",
    "summary": "Ở HSK 6, các bổ ngữ xu hướng và kết quả thoát khỏi nghĩa không gian vật lý để diễn tả quá trình biến đổi xã hội, tổng hợp tư duy và chuyển hóa kết quả trong văn bản học thuật.",
    "deepNotesHtml": "<p><strong>1. Bổ ngữ xu hướng trong câu nghị luận trừu tượng:</strong><br>- <code>V + 起来</code>: không chỉ là \"bắt đầu\", mà còn mang nghĩa <strong>tập hợp, gộp chung, liên kết lại</strong>: <code>把理论和实践结合起来</code> (kết hợp lý luận với thực tiễn), <code>加起来</code> (cộng gộp lại), <code>总结起来</code> (tổng kết lại).<br>- <code>V + 下来</code>: mang nghĩa <strong>định hình ổn định, giữ vững lâu dài</strong> giữa biến động: <code>固定下来</code> (cố định lại), <code>平静下来</code> (lắng dịu lại), <code>保留下来</code> (bảo tồn giữ lại).<br>- <code>V + 出来</code>: bộc lộ bản chất ẩn bên trong ra ngoài: <code>体现出来</code> (thể hiện rõ ra), <code>流露出来</code> (bộc lộ cảm xúc).</p><p><strong>2. Bổ ngữ kết quả văn viết <code>V + 到</code> và <code>V + 成</code>:</strong><br>- <code>V + 到</code> chỉ đạt tới mức độ/giai đoạn cao: <code>认识不到</code> (chưa nhận thức tới), <code>上升到新高度</code> (nâng lên tầm cao mới).<br>- <code>V + 成</code> chỉ sự chuyển hóa hoặc định hình bản thể: <code>演变成为</code> (diễn biến thành), <code>划分成</code> (phân chia thành).</p>",
