        "zh": "只有把个人理想与社会需求结合起来，才能实现更大的人生价值。",
        "py": "Zhǐyǒu bǎ gèrén lǐxiǎng yǔ shèhuì xūqiú jiéhé qǐlái, cái néng shíxiàn gèng dà de rénshēng jiàzhí.",
        "vi": "Chỉ có kết hợp lý tưởng cá nhân với nhu cầu xã hội lại với nhau mới có thể thực hiện giá trị cuộc sống lớn lao hơn."
