    "formula": "画蛇添足 (vẽ rắn thêm chân)  |  自相矛盾 (tự mâu thuẫn)  |  弄巧成拙 (khéo quá hóa vụng)  |  适得其反 (phản tác dụng)",
    "summary": "Bốn thành ngữ kinh điển bắt nguồn từ ngụ ngôn và biện luận, chuyên dùng để chỉ trích sai lầm tư duy hoặc hành động làm hỏng việc ở HSK 6. Nắm rõ sắc thái khác biệt giữa 'làm thừa' (画蛇添足) và 'tạo kết quả ngược lại' (适得其反) là rất cần thiết.",
    "deepNotesHtml": "<p><strong>1. So sánh sắc thái 4 thành ngữ dễ nhầm:</strong><br>- <code>画蛇添足</code> (huàshé-tiānzú — vẽ rắn thêm chân): bản thân việc chính đã hoàn thiện rồi nhưng làm thừa thêm một bước vô ích khiến hỏng cả việc (ví dụ câu văn đã súc tích lại cố viết thêm đoạn rườm rà).<br>- <code>自相矛盾</code> (zìxiāng-máodùn — tự mâu thuẫn với chính mình): lời nói trước và sau đá nhau chan chát, không nhất quán về mặt logic.<br>- <code>弄巧成拙</code> (nòngqiǎo-chéngzhuō — muốn tỏ ra khéo léo lại hóa vụng về): chủ ý muốn khoe tài hoặc dùng mẹo khôn ngoan nhưng kết cục lại tự làm lộ khuyết điểm hay hỏng việc.<br>- <code>适得其反</code> (shìdé-qífǎn — đạt kết quả ngược hẳn kỳ vọng): mong muốn kết quả A nhưng phương pháp sai khiến kết quả lại biến thành B trái ngược hoàn toàn (thường dùng cho phương pháp giáo dục, tiếp thị hay chăm sóc).</p><p><strong>2. Điểm chung:</strong> Cả bốn đều mang sắc thái phê phán/cảnh báo, rất hay xuất hiện trong phần chọn câu sai logic hoặc bài đọc bình luận HSK 6.</p>",
