      "❌ 这件事情很简单，可谓任重道远 → Ngược nghĩa! 任重道远 chỉ dùng cho sứ mệnh lớn lao và kéo dài lâu năm.",
      "❌ 他对学习很德才兼备 → ✅ 他是一个德才兼备的学生 (德才兼备 là đánh giá con người/nhân tài, không gắn sau 很 với nghĩa 'rất chăm học')."
