    "title": "Thành ngữ HSK 6 về Thời cuộc & Biến đổi (与日俱增 / 日新月异 / 潜移默化 / 层出不穷)",
    "formula": "与日俱增 (tăng theo từng ngày)  |  日新月异 (đổi mới từng ngày)  |  潜移默化 (thấm dần âm thầm)  |  层出不穷 (nối tiếp xuất hiện không ngớt)",
    "summary": "Bốn thành ngữ miêu tả tốc độ biến chuyển của xã hội hiện đại, công nghệ và ảnh hưởng văn hóa trong đề thi HSK 6. Phân biệt rõ: '日新月异' nhấn mạnh tốc độ phát triển thay mới, '层出不穷' nhấn mạnh số lượng sự vật mới liên tiếp ra đời, còn '潜移默化' chỉ tác động âm thầm lên tư tưởng.",
    "deepNotesHtml": "<p><strong>1. Phân biệt 4 thành ngữ biến đổi cấp cao:</strong><br>- <code>与日俱增</code> (yǔrì-jùzēng — cùng năm tháng mà tăng dần lên): chỉ mức độ, nhu cầu, số lượng hoặc tình cảm tăng trưởng liên tục theo thời gian (<code>压力与日俱增</code>, <code>需求与日俱增</code>).<br>- <code>日新月异</code> (rìxīn-yuèyì — ngày mới tháng khác): tốc độ phát triển, đổi mới của khoa học công nghệ hay diện mạo đô thị cực kỳ nhanh chóng.<br>- <code>层出不穷</code> (céngchū-bùqióng — hết lớp này đến lớp khác không cạn): những sự vật, hiện tượng, sản phẩm hoặc vấn đề mới liên tiếp xuất hiện dồn dập (có thể dùng cho cả nghĩa tốt như nhân tài/sáng kiến lẫn nghĩa xấu như chiêu trò lừa đảo).<br>- <code>潜移默化</code> (qiányí-mòhuà — âm thầm chuyển biến): sự ảnh hưởng sâu sắc nhưng lặng lẽ của môi trường, gia đình hay sách vở lên tính cách con người theo thời gian dài.</p><p><strong>2. Mẹo đặt câu:</strong> <code>潜移默化</code> hay đi với <code>地影响</code> hoặc làm định ngữ <code>潜移默化的影响</code>.</p>",
